function render(){const q=document.getElementById('search').value.toLowerCase(),s=document.getElementById('statusFilter').value;const list=orders.filter(o=>(!s||o.status===s)&&Object.values(o).join(' ').toLowerCase().includes(q));document.getElementById('orderRows').innerHTML=list.length?list.map((o,i)=>`<tr onclick="openDetail('${o.id}')"><td><div class="order">${o.id}</div><div class="sub">${o.ship}</div></td><td><div class="route">${o.from} → ${o.to}</div><div class="sub">${o.customer}</div></td><td><span class="badge ${badge[o.status]}">${o.status}</span></td><td>${o.driver}<div class="sub">${o.car}</div></td><td><div style="color:${o.alert?'var(--red)':'inherit'}">${o.latest}</div><div class="sub">${o.time}</div></td><td><div class="actions"><button class="iconbtn" title="查看" onclick="event.stopPropagation();openDetail('${o.id}')">⌕</button><button class="iconbtn" title="二维码" onclick="event.stopPropagation();openQR('${o.id}')">▦</button><button class="iconbtn" title="更正" onclick="event.stopPropagation();openEdit('${o.id}')">✎</button></div></td></tr>`).join(''):'<tr><td colspan="6" class="empty">未找到符合条件的物流订单</td></tr>'}
