function detailHTML(o){return `<div class="summary"><div class="mini"><span>物流状态</span><b class="badge ${badge[o.status]}">${o.status}</b></div><div class="mini"><span>商品数量</span><b>${o.qty}箱</b></div><div class="mini"><span>最新温度</span><b style="color:${o.temp>4?'var(--red)':'var(--green)'}">${o.temp}℃</b></div><div class="mini"><span>现场凭证</span><b>13张</b></div></div><div class="section"><div class="section-head"><h3>物流进度</h3><button class="btn" onclick="openQR('${o.id}')">▦ 查看二维码</button></div><div class="section-body"><div class="timeline"><div class="node"><i>✓</i><b>工厂发货</b><small>08-05 09:18</small></div><div class="node"><i>✓</i><b>司机揽收</b><small>08-05 10:06</small></div><div class="node ${['待揽收','运输中'].includes(o.status)?'pending':''}"><i>${['待揽收','运输中'].includes(o.status)?'3':'✓'}</i><b>到货签收</b><small>${['待揽收','运输中'].includes(o.status)?'待完成':'08-05 14:32'}</small></div><div class="node ${o.status!=='已完成'?'pending':''}"><i>${o.status==='已完成'?'✓':'4'}</i><b>甲方确认</b><small>${o.status==='已完成'?'08-05 15:10':'待完成'}</small></div></div></div></div>${stage('工厂发货','王志强 · 工厂物流','08-05 09:18',o,5)}${stage('司机揽收',o.driver+' · '+o.car,'08-05 10:06',o,3)}${stage('到货签收','上海九亭冷链仓 · 陈师傅','08-05 14:32',o,5)}<div class="section"><div class="section-head"><h3>更正与操作记录</h3></div><div class="section-body"><div class="kv"><span>最后操作</span><b>系统创建订单</b><span>操作时间</span><b>08-05 08:55</b><span>数据版本</span><b>V1 · 无更正</b><span>操作账号</span><b>admin_zhou</b></div></div></div>`}
function stage(title,person,time,o,count){return `<div class="section"><div class="section-head"><h3>${title}</h3><button class="btn" onclick="openEdit('${o.id}','${title}')">✎ 手动更正</button></div><div class="section-body"><div class="kv"><span>提交人员</span><b>${person}</b><span>提交时间</span><b>${time}</b><span>货物数量</span><b>${o.qty}箱</b><span>车厢温度</span><b>${o.temp}℃</b><span>封签号</span><b>FS-260805-117</b><span>定位状态</span><b style="color:var(--green)">位置正常</b></div><div class="photos">${Array.from({length:count},(_,i)=>`<div class="photo">现场照片<br>${i+1}</div>`).join('')}</div></div></div>`}
function openDetail(id){current=orders.find(o=>o.id===id);document.getElementById('detailTitle').textContent=current.id;document.getElementById('detailSub').textContent=`${current.ship} · ${current.customer}`;document.getElementById('detailBody').innerHTML=detailHTML(current);document.getElementById('overlay').classList.add('show');document.getElementById('drawer').classList.add('show')}
function openEdit(id,stage){current=orders.find(o=>o.id===id);document.getElementById('editDesc').textContent=`${current.id} · 当前版本 V1`;document.getElementById('editStage').value=stage||'工厂发货';document.getElementById('editQty').value=current.qty;document.getElementById('editTemp').value=current.temp;document.getElementById('editReason').value='';showModal('editModal')}
function saveEdit(){const reason=document.getElementById('editReason').value.trim();if(!reason){toast('请填写修改原因');return}current.qty=+document.getElementById('editQty').value||current.qty;current.temp=+document.getElementById('editTemp').value||current.temp;closeModal();render();if(document.getElementById('drawer').classList.contains('show'))document.getElementById('detailBody').innerHTML=detailHTML(current);toast('更正成功，已生成 V2 操作记录')}
function openQR(id){current=orders.find(o=>o.id===id);if(!current||current.ship==='未创建'){toast('请先创建发货单');return}document.getElementById('qrOrder').textContent=`${current.ship} · 版本 V${current.qrVersion||1}`;const status=document.getElementById('qrSecurityStatus');status.textContent=current.qrStatus==='已作废'?'令牌已作废':'令牌有效';status.className=`badge ${current.qrStatus==='已作废'?'red':'green'}`;document.getElementById('qrSecurityMeta').textContent=`访问限频 · 身份校验 · ${current.qrStatus==='已作废'?'扫码已禁止':'分阶段授权'}`;const box=document.getElementById('qrbox');box.innerHTML='';let seed=[...`${id}-${current.qrVersion||1}`].reduce((a,c)=>a+c.charCodeAt(0),0);for(let y=0;y<21;y++)for(let x=0;x<21;x++){const i=document.createElement('i');const finder=(x<7&&y<7)||(x>13&&y<7)||(x<7&&y>13);seed=(seed*9301+49297)%233280;const on=finder?((x%7===0||y%7===0||x%7===6||y%7===6)||(x%7>=2&&x%7<=4&&y%7>=2&&y%7<=4)):seed/233280>.5;if(on)i.className='on';box.appendChild(i)}box.style.opacity=current.qrStatus==='已作废'?'.22':'1';showModal('qrModal')}
function revokeQR(){if(!current||current.qrStatus==='已作废'){toast('二维码已处于作废状态');return}if(!window.confirm(`请再次确认：立即作废 ${current.ship} 的二维码？作废后司机无法继续扫码访问。`))return;current.qrStatus='已作废';current.qrRevokedAt=new Date().toLocaleString('zh-CN',{hour12:false});openQR(current.id);toast('二维码已作废')}
function regenerateQR(){if(!current)return;if(!window.confirm(`请再次确认：重新生成 ${current.ship} 的二维码？旧二维码将永久失效。`))return;current.qrVersion=(current.qrVersion||1)+1;current.qrStatus='有效';current.qrRegeneratedAt=new Date().toLocaleString('zh-CN',{hour12:false});openQR(current.id);toast('新二维码已生成，旧令牌已失效')}
function localInput(d){const z=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${z(d.getMonth()+1)}-${z(d.getDate())}T${z(d.getHours())}:${z(d.getMinutes())}`}
function openCreate(){const now=new Date(),eta=new Date(now.getTime()+48*3600000);document.getElementById('newShipTime').value=localInput(now);document.getElementById('newEta').value=localInput(eta);['newCustomer','newContact','newTo','newBatch','newQty','newDriver','newDriverPhone','newCar','newCarrier','newSeal','newRemark'].forEach(id=>document.getElementById(id).value='');showModal('createModal')}
function shipmentData(){const customer=document.getElementById('newCustomer').value.trim(),to=document.getElementById('newTo').value.trim(),qty=+document.getElementById('newQty').value,batch=document.getElementById('newBatch').value.trim(),contact=document.getElementById('newContact').value.trim();if(!customer||!to||!qty||!batch||!contact){toast('请完整填写客户、联系人、仓库、批次和箱数');return null}const stamp=String(Date.now()).slice(-8),day=new Date().toISOString().slice(0,10).replaceAll('-','');return{id:`ORD${day}${stamp}`,ship:`FHD${day}${stamp}`,customer,from:document.getElementById('newFrom').value,to,status:'待发货',driver:document.getElementById('newDriver').value.trim()||'待分配',car:document.getElementById('newCar').value.trim()||'待分配',latest:'发货单已创建',time:'刚刚',qty,temp:0,alert:false}}
function createShipment(){const data=shipmentData();if(!data)return;orders.unshift(data);current=data;closeModal();render();toast('发货单创建成功，二维码已生成');setTimeout(()=>openQR(data.id),650)}
function saveDraft(){const data=shipmentData();if(!data)return;data.latest='草稿待完善';orders.unshift(data);closeModal();render();toast('发货单草稿已保存')}
function render(){const q=document.getElementById('search').value.toLowerCase(),s=document.getElementById('statusFilter').value;const list=orders.filter(o=>(!s||o.status===s)&&Object.values(o).join(' ').toLowerCase().includes(q));document.getElementById('orderRows').innerHTML=list.length?list.map(o=>{const source=o.status==='待创建发货单',unit=o.unit||'箱',ops=source?`<button class="iconbtn" title="查看平台订单" onclick="event.stopPropagation();openDetail('${o.id}')">⌕</button><button class="iconbtn" title="创建发货单" onclick="event.stopPropagation();openCreate('${o.id}')">＋</button>`:`<button class="iconbtn" title="查看物流" onclick="event.stopPropagation();openDetail('${o.id}')">⌕</button><button class="iconbtn" title="二维码" onclick="event.stopPropagation();openQR('${o.id}')">▦</button><button class="iconbtn" title="变更司机" onclick="event.stopPropagation();openAdminDriverChange('${o.id}')">⇄</button><button class="iconbtn" title="更正节点" onclick="event.stopPropagation();openEdit('${o.id}')">✎</button>`;return `<tr onclick="openDetail('${o.id}')"><td><div class="order">${o.id}</div><div class="sub">${source?'平台订单 · '+o.source:'发货单 · '+o.ship}</div></td><td><div class="route">${o.from} → ${o.to}</div><div class="sub">${o.customer} · ${o.qty}${unit}</div></td><td><span class="badge ${badge[o.status]}">${o.status}</span>${o.slaOverdue?'<div class="sub" style="color:var(--red)">⏰ 节点已超时</div>':''}</td><td>${o.driver}<div class="sub">${o.logisticsCompany?adminEscape(o.logisticsCompany)+' · ':''}${o.driverPhone||o.car}${o.driverChanges?.length?` · 已变更${o.driverChanges.length}次`:''}</div></td><td><div style="color:${o.alert?'var(--red)':'inherit'}">${o.latest}</div><div class="sub">${o.time}${o.exceptions?.length?' · ⚠ '+o.exceptions.length+'个异常':''}${o.notifications?.length?' · 🔔 '+o.notifications.length+'条通知':''}</div></td><td><div class="actions">${ops}</div></td></tr>`}).join(''):'<tr><td colspan="6" class="empty">未找到符合条件的订单</td></tr>'}
function sourceOrderHTML(o){const products=(o.products||[]).map(p=>`<div class="goods" style="margin-bottom:9px"><div class="goods-head"><span>${p.name}</span><span class="qty">× ${p.qty}${p.unit||'箱'}</span></div><div class="goods-meta">${p.spec}</div><div class="summary-row"><span>成交价</span><b>¥${p.price.toFixed(2)}　小计 ¥${(p.price*p.qty).toFixed(2)}</b></div></div>`).join('');return `<div class="summary"><div class="mini"><span>订单状态</span><b class="badge gray">${o.status}</b></div><div class="mini"><span>商品数量</span><b>${o.qty}${o.unit||'箱'}</b></div><div class="mini"><span>应付金额</span><b>¥${o.amount.toFixed(2)}</b></div><div class="mini"><span>发货单</span><b>未创建</b></div></div><div class="section"><div class="section-head"><h3>平台订单信息</h3><button class="btn primary" onclick="openCreate('${o.id}')">创建发货单</button></div><div class="section-body"><div class="kv"><span>订单号</span><b>${o.id}</b><span>订单来源</span><b>${o.source}</b><span>买家</span><b>${o.customer}</b><span>发货主体</span><b>${o.from}</b><span>收货人</span><b>${o.receiver}</b><span>甲方手机号</span><b>${o.buyerPhone}</b><span>收货地址</span><b style="grid-column:span 3">${o.address}</b></div></div></div><div class="section"><div class="section-head"><h3>订单商品</h3><span class="badge green">订单自动带入</span></div><div class="section-body">${products}<div class="summary-row"><span>商品合计</span><b style="color:var(--red);font-size:16px">${o.qty}${o.unit} · ¥${o.amount.toFixed(2)}</b></div></div></div><div class="section"><div class="section-head"><h3>当前数据流程</h3></div><div class="section-body"><div class="timeline"><div class="node"><i>✓</i><b>平台已接单</b><small>08-05 13:48</small></div><div class="node pending"><i>2</i><b>创建发货单</b><small>待操作</small></div><div class="node pending"><i>3</i><b>司机履约</b><small>未开始</small></div><div class="node pending"><i>4</i><b>甲方确认</b><small>未开始</small></div></div></div></div>`}
function shipmentFlowHTML(o){const products=(o.products||[]).map(p=>`<div class="goods" style="margin-bottom:8px"><div class="goods-head"><span>${p.name}</span><span class="qty">× ${p.qty}${p.unit||'箱'}</span></div><div class="goods-meta">${p.spec}</div></div>`).join('');const step=o.status==='待揽收'?1:o.status==='运输中'?2:o.status==='待确认'?3:4,names=['发货单已创建','司机揽收','到货签收','甲方确认'];return `<div class="summary"><div class="mini"><span>物流状态</span><b class="badge ${badge[o.status]}">${o.status}</b></div><div class="mini"><span>商品数量</span><b>${o.qty}${o.unit||'箱'}</b></div><div class="mini"><span>司机绑定</span><b>${o.driverPhone||'未绑定'}</b></div><div class="mini"><span>甲方绑定</span><b>${o.buyerPhone||'未绑定'}</b></div></div><div class="section"><div class="section-head"><h3>履约数据流程</h3><button class="btn" onclick="openQR('${o.id}')">▦ 查看二维码</button></div><div class="section-body"><div class="timeline">${names.map((n,i)=>`<div class="node ${i>=step?'pending':''}"><i>${i<step?'✓':i+1}</i><b>${n}</b><small>${i<step?'已完成':'待完成'}</small></div>`).join('')}</div></div></div><div class="section"><div class="section-head"><h3>手机号绑定关系</h3></div><div class="section-body"><div class="kv"><span>平台订单</span><b>${o.id}</b><span>发货单</span><b>${o.ship}</b><span>司机</span><b>${o.driver} · ${o.driverPhone}</b><span>车辆</span><b>${o.car}</b><span>甲方收货人</span><b>${o.receiver}</b><span>甲方手机号</span><b>${o.buyerPhone}</b></div></div></div><div class="section"><div class="section-head"><h3>订单商品</h3><span class="badge green">平台订单带入</span></div><div class="section-body">${products}</div></div><div class="section"><div class="section-head"><h3>节点提交信息</h3></div><div class="section-body"><div class="audit">当前状态：${o.status}。发货、揽收、签收、甲方确认的数据分别按节点保存，后台更正必须保留原值和修改原因。</div></div></div>`}
function nodeDetailCard(o,title,done,info,photos){const edited=o.nodeEdits?.[title];if(edited?.fields)info=edited.fields;return `<div class="section"><div class="section-head"><h3>${title}</h3><div style="display:flex;gap:7px;align-items:center"><span class="badge ${done?'green':'gray'}">${done?'已完成':'待提交'}</span>${edited?'<span class="badge amber">已更正 V'+(o.version||2)+'</span>':''}${done?`<button class="btn" onclick="openEdit('${o.id}','${title}')">✎ 手动更正</button>`:''}</div></div><div class="section-body">${done?`<div class="kv">${info.map(x=>`<span>${x[0]}</span><b>${x[1]}</b>`).join('')}</div><div class="photos">${Array.from({length:photos},(_,i)=>`<div class="photo">${title}照片<br>${i+1}</div>`).join('')}</div>${edited?`<div class="audit" style="margin-top:12px">更正原因：${edited.reason}　·　操作人：周婷　·　${edited.time}</div>`:''}`:`<div class="empty" style="padding:24px">该节点尚未提交，暂无人员、时间、位置及照片信息</div>`}</div></div>`}
function shipmentDetailHTML(o){const unit=o.unit||'箱',level=o.status==='待揽收'?1:o.status==='运输中'?2:o.status==='待确认'?3:o.status==='已完成'?4:2,products=(o.products||[]).map(p=>`<div class="goods" style="margin-bottom:8px"><div class="goods-head"><span>${p.name}</span><span class="qty">× ${p.qty}${p.unit||'箱'}</span></div><div class="goods-meta">${p.spec}</div></div>`).join('')||`<div class="goods"><div class="goods-head"><span>脱骨侠商品</span><span class="qty">× ${o.qty}${unit}</span></div><div class="goods-meta">商品69码、单包规格、每箱包数及批次由平台订单带入</div></div>`;const names=['工厂发货','司机揽收','到货签收','甲方确认'];const timeline=`<div class="timeline">${names.map((n,i)=>`<div class="node ${i>=level?'pending':''}"><i>${i<level?'✓':i+1}</i><b>${n}</b><small>${i<level?'已完成':'待完成'}</small></div>`).join('')}</div>`;const factory=[['提交人员','王志强 · 工厂物流'],['提交时间','2026-08-06 13:48'],['发货数量',`${o.qty}${unit}`],['装车温度',`${o.temp||2.3}℃`],['发货仓库',o.from],['司机手机号',o.driverPhone||'未绑定'],['车辆',`${o.driver} · ${o.car}`],['封签号','未填写（选填）']];const pickup=[['提交人员',`${o.driver} · 承运司机`],['揽收时间','2026-08-06 14:26'],['实收数量',`${o.qty}${unit}`],['装车温度','2.4℃'],['现场位置',`${o.from}装货区`],['车辆',o.car],['异常情况','无异常'],['封签核验','无封签']];const sign=[['提交人员',`${o.driver} · 承运司机`],['到达时间','2026-08-07 12:35'],['交付数量',`${o.qty}${unit}`],['开箱前温度','2.6℃'],['到货位置',o.to],['现场收货人',o.receiver||'甲方收货人'],['交付结果','正常签收'],['异常情况','无异常']];const confirm=[['确认人员',`${o.receiver||'甲方管理员'}`],['确认时间','2026-08-07 13:02'],['确认数量',`${o.qty}${unit}`],['甲方手机号',o.buyerPhone||'未绑定'],['核验结果','商品、数量、温度、封签一致'],['确认结论','确认收货'],['备注','无']];return `<div class="summary"><div class="mini"><span>物流状态</span><b class="badge ${badge[o.status]}">${o.status}</b></div><div class="mini"><span>商品数量</span><b>${o.qty}${unit}</b></div><div class="mini"><span>司机绑定</span><b>${o.driverPhone||'未绑定'}</b></div><div class="mini"><span>甲方绑定</span><b>${o.buyerPhone||'未绑定'}</b></div></div><div class="section"><div class="section-head"><h3>发货单基本信息</h3><button class="btn" onclick="openQR('${o.id}')">▦ 查看二维码</button></div><div class="section-body"><div class="kv"><span>平台订单号</span><b>${o.id}</b><span>发货单号</span><b>${o.ship}</b><span>客户</span><b>${o.customer}</b><span>运输路线</span><b>${o.from} → ${o.to}</b><span>司机绑定</span><b>${o.driver} · ${o.driverPhone||''}</b><span>甲方绑定</span><b>${o.receiver||''} · ${o.buyerPhone||''}</b></div></div></div><div class="section"><div class="section-head"><h3>履约进度</h3></div><div class="section-body">${timeline}</div></div><div class="section"><div class="section-head"><h3>商品明细</h3><span class="badge green">平台订单带入</span></div><div class="section-body">${products}</div></div>${nodeDetailCard(o,'工厂发货',level>=1,factory,5)}${nodeDetailCard(o,'司机揽收',level>=2,pickup,3)}${nodeDetailCard(o,'到货签收',level>=3,sign,5)}${nodeDetailCard(o,'甲方确认',level>=4,confirm,0)}<div class="section"><div class="section-head"><h3>操作与更正记录</h3></div><div class="section-body"><div class="kv"><span>数据版本</span><b>V1</b><span>最后更新</span><b>${o.time}</b><span>操作账号</span><b>admin_zhou</b><span>更正记录</span><b>暂无更正</b></div></div></div>`}
function openDetail(id){current=orders.find(o=>o.id===id);document.getElementById('detailTitle').textContent=current.status==='待创建发货单'?'平台订单详情':current.ship;document.getElementById('detailSub').textContent=`${current.id} · ${current.customer}`;document.getElementById('detailBody').innerHTML=current.status==='待创建发货单'?sourceOrderHTML(current):shipmentDetailHTML(current);if(current.status!=='待创建发货单'){injectStageSkuDetail(current);injectDeliveryConfirmationDetail(current);injectDriverChangeDetail(current)}document.getElementById('overlay').classList.add('show');document.getElementById('drawer').classList.add('show')}
function injectStageSkuDetail(o){const products=o.products?.length?o.products:[{name:'脱骨侠无骨鸡爪商品',barcode:'以订单为准',qty:o.qty,unit:o.unit||'箱'}],key=i=>`SKU${String(i+1).padStart(3,'0')}`,plan=Object.fromEntries(products.map((p,i)=>[key(i),p.qty])),maps=[plan,o.factorySkuQty||plan,o.pickupSkuQty||o.factorySkuQty||plan,o.arrivalSkuQty||o.pickupSkuQty||o.factorySkuQty||plan,o.buyerSkuQty||o.arrivalSkuQty||o.pickupSkuQty||o.factorySkuQty||plan],section=document.createElement('div');section.className='section';section.innerHTML=`<div class="section-head"><h3>逐商品数量对账</h3><span class="badge ${o.exceptions?.length?'red':'green'}">${o.exceptions?.length?'存在差异工单':'数量链路完整'}</span></div><div class="section-body" style="overflow:auto"><table><thead><tr><th>商品</th><th>订单计划</th><th>工厂发货</th><th>司机揽收</th><th>司机到货</th><th>甲方签收</th></tr></thead><tbody>${products.map((p,i)=>{const k=key(i);return `<tr><td>${adminEscape(p.name)}<div class="sub">69码 ${adminEscape(p.barcode||'待补充')}</div></td>${maps.map(m=>`<td>${m[k]??p.qty}${p.unit||'箱'}</td>`).join('')}</tr>`}).join('')}</tbody></table></div>`;document.getElementById('detailBody').append(section)}
function injectDeliveryConfirmationDetail(o){const unit=o.unit||'箱',done=o.status==='已完成',section=document.createElement('div');section.className='section';section.innerHTML=`<div class="section-head"><h3>数量确认与甲方签收资料</h3><span class="badge ${done?'green':'amber'}">${done?'甲方已确认':'履约中'}</span></div><div class="section-body"><div class="kv"><span>订单计划数量</span><b>${o.qty}${unit}</b><span>工厂实际发货</span><b>${o.factoryQty||o.qty}${unit}</b><span>司机确认发货</span><b>${o.pickupQty||o.factoryQty||o.qty}${unit}</b><span>司机确认到货</span><b>${o.arrivalQty||o.pickupQty||o.qty}${unit}</b><span>甲方实际签收</span><b>${done?(o.buyerSignedQty||o.arrivalQty||o.qty)+unit:'待确认'}</b><span>签收人</span><b>${done?(o.buyerSignerName||o.receiver||'甲方收货人'):'待填写'}</b><span>签收人手机号</span><b>${done?(o.buyerSignerPhone||o.buyerPhone||'待补充'):'待填写'}</b><span>签收照片</span><b>${done?(o.buyerSignPhotoName||'已上传1张'):'待上传'}</b><span>签收单（选填）</span><b>${done?(o.buyerReceiptDocumentName||'未上传'):'待确认'}</b><span>二次确认</span><b>${done?'已完成，确认时间 '+(o.buyerConfirmedAt||'2026-08-07 13:02'):'待甲方操作'}</b></div>${done?'<div class="photos"><div class="photo">甲方签收照片<br>点击查看</div></div>':''}</div>`;document.getElementById('detailBody').append(section)}
function injectDriverChangeDetail(o){const body=document.getElementById('detailBody'),basic=[...body.querySelectorAll('.section-head h3')].find(x=>x.textContent==='发货单基本信息');if(basic){const actions=document.createElement('div');actions.style.display='flex';actions.style.gap='8px';actions.innerHTML=`<button class="btn primary" onclick="openAdminDriverChange('${o.id}')">⇄ 变更司机</button>`;basic.parentElement.append(actions);const kv=basic.closest('.section').querySelector('.kv');kv.insertAdjacentHTML('beforeend',`<span>物流公司</span><b>${adminEscape(o.logisticsCompany||'历史订单未关联')}</b><span>车辆类型</span><b>${adminEscape(o.vehicleType||'冷藏运输车辆')}</b>`)}const records=o.driverChanges||[],section=document.createElement('div');section.className='section';section.innerHTML=`<div class="section-head"><h3>司机与车辆变更记录</h3><span class="badge ${records.length?'amber':'gray'}">${records.length?`已变更 ${records.length} 次`:'暂无变更'}</span></div><div class="section-body">${records.length?records.slice().reverse().map((r,i)=>`<div class="audit" style="margin-bottom:${i===records.length-1?0:10}px"><b>${r.oldDriver||'未绑定'} ${r.oldPhone||''} → ${r.newDriver} ${r.newPhone}</b><br>车辆：${r.oldCar||'未绑定'} → ${r.newCar} · ${r.vehicleType}<br>原因：${r.reason}<br>操作人：${r.operator} · ${r.time}</div>`).join(''):'<div class="empty" style="padding:22px">当前预约司机未发生变更</div>'}</div>`;body.append(section)}
function openAdminDriverChange(id){const o=orders.find(x=>x.id===id);if(!o||o.status==='待创建发货单'){toast('请先创建发货单');return}if(o.status==='已完成'){toast('已完成订单不能重新绑定司机，请使用节点更正');return}current=o;document.getElementById('adminDriverChangeDesc').textContent=`${o.ship} · ${o.customer}`;document.getElementById('adminDriverChangeCurrent').innerHTML=`当前绑定：<b>${o.driver||'未绑定'} ${o.driverPhone||''}</b> · ${o.car||'车辆待绑定'}<br>变更后原司机手机号将解除绑定，新司机可立即查看该发货单。`;document.getElementById('adminChangeDriver').value=o.driver==='待绑定'?'':o.driver||'';document.getElementById('adminChangeDriverPhone').value=o.driverPhone||'';document.getElementById('adminChangeCar').value=o.car==='待绑定'?'':o.car||'';document.getElementById('adminChangeVehicleType').value=o.vehicleType||'9.6米冷藏厢式货车';document.getElementById('adminChangeReason').value='';showModal('driverChangeModal')}
function saveAdminDriverChange(){if(!current)return;const driver=document.getElementById('adminChangeDriver').value.trim(),driverPhone=document.getElementById('adminChangeDriverPhone').value.trim(),car=document.getElementById('adminChangeCar').value.trim(),vehicleType=document.getElementById('adminChangeVehicleType').value,reason=document.getElementById('adminChangeReason').value.trim();if(!driver||!/^1\d{10}$/.test(driverPhone)||!car||!reason){toast('请完整填写新司机、11位手机号、车辆和变更原因');return}if(driver===current.driver&&driverPhone===current.driverPhone&&car===current.car&&vehicleType===(current.vehicleType||'9.6米冷藏厢式货车')){toast('司机与车辆信息没有变化');return}if(!window.confirm(`请再次确认：将司机变更为 ${driver}（${driverPhone}），车辆 ${car}。是否继续？`))return;const record={oldDriver:current.driver||'未绑定',oldPhone:current.driverPhone||'',oldCar:current.car||'',newDriver:driver,newPhone:driverPhone,newCar:car,vehicleType,reason,operator:'周婷 · 物流管理员',time:new Date().toLocaleString('zh-CN',{hour12:false})};current.driverChanges=current.driverChanges||[];current.driverChanges.push(record);Object.assign(current,{driver,driverPhone,car,vehicleType,latest:`预约司机已变更：${record.oldDriver} → ${driver}`,time:'刚刚',version:(current.version||1)+1});const id=current.id;closeModal();render();openDetail(id);toast('司机变更成功，原手机号解绑，新手机号已绑定')}
function adminEscape(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function adminDateValid(value){return !value||value>='2026-08-10'}
function adminVehicleQualified(v){return adminDateValid(v.inspectionExpiry)&&adminDateValid(v.coldChainExpiry)}
function adminDriverQualified(d){return d.status==='启用'&&adminDateValid(d.licenseExpiry)&&d.vehicles.some(adminVehicleQualified)}
function companyById(id){return logisticsCompanies.find(x=>x.id===id)}
function switchAdminView(view){const names=['orders','companies','drivers','exceptions'];names.forEach(name=>{document.getElementById(`${name}View`).hidden=name!==view;document.getElementById(`nav${name[0].toUpperCase()+name.slice(1)}`).classList.toggle('active',name===view)});document.getElementById('adminPageTitle').textContent={orders:'物流订单管理',companies:'物流公司管理',drivers:'司机与车辆管理',exceptions:'异常工单与更正审核'}[view];if(view==='companies')renderCompanyManagement();if(view==='drivers')renderDriverManagement();if(view==='exceptions')renderExceptionManagement()}
function renderCompanyManagement(){document.getElementById('companyTotal').textContent=logisticsCompanies.length;document.getElementById('companyEnabled').textContent=logisticsCompanies.filter(x=>x.status==='启用').length;document.getElementById('companyDriverTotal').textContent=managedDrivers.length;document.getElementById('companyRows').innerHTML=logisticsCompanies.map(c=>{const count=managedDrivers.filter(d=>d.companyId===c.id).length;return `<tr><td><div class="order">${adminEscape(c.name)}</div><div class="sub">${c.id}${c.creditCode?' · '+adminEscape(c.creditCode):''}</div></td><td>${adminEscape(c.contact)}</td><td>${adminEscape(c.phone)}</td><td>${adminEscape(c.address)}</td><td><button class="btn link-count" onclick="showCompanyDrivers('${c.id}')">${count} 名司机</button></td><td><button class="status-switch ${c.status==='启用'?'on':'off'}" onclick="toggleCompanyStatus('${c.id}')">${c.status}</button></td><td><div class="actions"><button class="btn" onclick="openCompanyEditor('${c.id}')">编辑</button><button class="btn" onclick="showCompanyDrivers('${c.id}')">司机</button></div></td></tr>`}).join('')}
function openCompanyEditor(id=''){const c=companyById(id);document.getElementById('companyModalTitle').textContent=c?'编辑物流公司':'新增物流公司';document.getElementById('companyEditId').value=c?.id||'';document.getElementById('companyName').value=c?.name||'';document.getElementById('companyCreditCode').value=c?.creditCode||'';document.getElementById('companyContact').value=c?.contact||'';document.getElementById('companyPhone').value=c?.phone||'';document.getElementById('companyAddress').value=c?.address||'';document.getElementById('companyStatus').value=c?.status||'启用';document.getElementById('companyRemark').value=c?.remark||'';showModal('companyModal')}
function saveCompany(){const id=document.getElementById('companyEditId').value,name=document.getElementById('companyName').value.trim(),contact=document.getElementById('companyContact').value.trim(),phone=document.getElementById('companyPhone').value.trim(),address=document.getElementById('companyAddress').value.trim();if(!name||!contact||!/^1\d{10}$/.test(phone)||!address){toast('请完整填写公司名称、联系人、11位手机号和地址');return}if(!window.confirm(`请再次确认：${id?'保存物流公司修改':'新增物流公司“'+name+'”'}？`))return;const data={name,creditCode:document.getElementById('companyCreditCode').value.trim(),contact,phone,address,status:document.getElementById('companyStatus').value,remark:document.getElementById('companyRemark').value.trim()};if(id)Object.assign(companyById(id),data);else logisticsCompanies.push({id:`LC${String(logisticsCompanies.length+1).padStart(3,'0')}`,...data});closeModal();refreshCompanySelectors();renderCompanyManagement();renderDriverManagement();toast(id?'物流公司已更新':'物流公司已新增')}
function toggleCompanyStatus(id){const c=companyById(id),next=c.status==='启用'?'停用':'启用';if(!window.confirm(`请再次确认：将“${c.name}”设为${next}？${next==='停用'?'停用后不可用于新发货单选择。':''}`))return;c.status=next;refreshCompanySelectors();renderCompanyManagement();toast(`物流公司已${next}`)}
function showCompanyDrivers(id){switchAdminView('drivers');document.getElementById('driverCompanyFilter').value=id;renderDriverManagement()}
function refreshCompanySelectors(){const options=logisticsCompanies.map(c=>`<option value="${c.id}">${adminEscape(c.name)}${c.status==='停用'?'（停用）':''}</option>`).join(''),driverCompany=document.getElementById('driverCompany'),filter=document.getElementById('driverCompanyFilter');if(driverCompany){const old=driverCompany.value;driverCompany.innerHTML=options;driverCompany.value=old||logisticsCompanies[0]?.id||''}if(filter){const old=filter.value;filter.innerHTML='<option value="">全部物流公司</option>'+options;filter.value=old}refreshShipmentCompanyOptions()}
function renderDriverManagement(){const q=(document.getElementById('driverSearch')?.value||'').toLowerCase(),companyId=document.getElementById('driverCompanyFilter')?.value||'';const list=managedDrivers.filter(d=>(!companyId||d.companyId===companyId)&&[d.name,d.phone,...d.vehicles.map(v=>v.plate)].join(' ').toLowerCase().includes(q));document.getElementById('driverTotal').textContent=managedDrivers.length;document.getElementById('driverEnabled').textContent=managedDrivers.filter(adminDriverQualified).length;document.getElementById('vehicleTotal').textContent=managedDrivers.reduce((n,d)=>n+d.vehicles.length,0);document.getElementById('driverRows').innerHTML=list.length?list.map(d=>{const qualified=adminDriverQualified(d);return `<tr><td><div class="order">${adminEscape(d.name)}</div><div class="sub">${d.id}</div></td><td>${adminEscape(companyById(d.companyId)?.name||'未关联')}</td><td>${adminEscape(d.phone)}</td><td>${d.vehicles.map(v=>`<span class="fleet-tag">${adminEscape(v.plate)} · ${adminEscape(v.type)}</span><div class="sub">年检 ${v.inspectionExpiry||'未录入'} · 冷链 ${v.coldChainExpiry||'未录入'}</div>`).join('')||'未登记'}</td><td>${adminEscape(d.license)} · ${d.licenseExpiry||'未录入'}<div class="sub" style="color:${qualified?'var(--green)':'var(--red)'}">${qualified?'资质有效，可用于发货':'资质过期/停用，不可选择'}</div></td><td><button class="status-switch ${d.status==='启用'?'on':'off'}" onclick="toggleDriverStatus('${d.id}')">${d.status}</button></td><td><div class="actions"><button class="btn" onclick="openDriverEditor('${d.id}')">编辑</button></div></td></tr>`}).join(''):'<tr><td colspan="7" class="empty">未找到符合条件的司机</td></tr>'}
function openDriverEditor(id=''){refreshCompanySelectors();const d=managedDrivers.find(x=>x.id===id),v=d?.vehicles?.[0]||{};document.getElementById('driverModalTitle').textContent=d?'编辑司机与车辆':'新增司机';document.getElementById('driverEditId').value=d?.id||'';document.getElementById('driverCompany').value=d?.companyId||logisticsCompanies.find(x=>x.status==='启用')?.id||'';document.getElementById('driverStatus').value=d?.status||'启用';document.getElementById('driverName').value=d?.name||'';document.getElementById('driverPhone').value=d?.phone||'';document.getElementById('driverIdCard').value=d?.idCard||'';document.getElementById('driverLicense').value=d?.license||'A2';document.getElementById('driverLicenseExpiry').value=d?.licenseExpiry||'2027-12-31';document.getElementById('vehiclePlate').value=v.plate||'';document.getElementById('vehicleType').value=v.type||'9.6米冷藏厢式货车';document.getElementById('vehicleLoad').value=v.load||'';document.getElementById('vehicleModel').value=v.model||'';document.getElementById('vehicleInspectionExpiry').value=v.inspectionExpiry||'2027-12-31';document.getElementById('vehicleColdChainExpiry').value=v.coldChainExpiry||'2027-12-31';showModal('driverModal')}
function saveDriver(){const id=document.getElementById('driverEditId').value,companyId=document.getElementById('driverCompany').value,name=document.getElementById('driverName').value.trim(),phone=document.getElementById('driverPhone').value.trim(),plate=document.getElementById('vehiclePlate').value.trim(),licenseExpiry=document.getElementById('driverLicenseExpiry').value,inspectionExpiry=document.getElementById('vehicleInspectionExpiry').value,coldChainExpiry=document.getElementById('vehicleColdChainExpiry').value;if(!companyId||!name||!/^1\d{10}$/.test(phone)||!plate||!licenseExpiry||!inspectionExpiry||!coldChainExpiry){toast('请完整填写司机、车辆及三项资质有效期');return}if(managedDrivers.some(d=>d.id!==id&&d.phone===phone)){toast('该手机号已关联其他司机');return}if(!window.confirm(`请再次确认：${id?'保存司机修改':'新增司机“'+name+'”'}并关联车辆 ${plate}？`))return;const data={companyId,name,phone,idCard:document.getElementById('driverIdCard').value.trim(),license:document.getElementById('driverLicense').value,licenseExpiry,status:document.getElementById('driverStatus').value,vehicles:[{plate,type:document.getElementById('vehicleType').value,load:document.getElementById('vehicleLoad').value.trim(),model:document.getElementById('vehicleModel').value.trim(),inspectionExpiry,coldChainExpiry}]};if(id)Object.assign(managedDrivers.find(x=>x.id===id),data);else managedDrivers.push({id:`DR${String(managedDrivers.length+1).padStart(3,'0')}`,...data});closeModal();renderCompanyManagement();renderDriverManagement();refreshShipmentCompanyOptions();toast(id?'司机与车辆已更新':'司机与车辆已新增')}
function toggleDriverStatus(id){const d=managedDrivers.find(x=>x.id===id),next=d.status==='启用'?'停用':'启用';if(!window.confirm(`请再次确认：将司机“${d.name}”设为${next}？${next==='停用'?'停用后不可用于新发货单选择。':''}`))return;d.status=next;renderDriverManagement();refreshShipmentCompanyOptions();toast(`司机已${next}`)}
function prepareFleetSelectors(){const modal=document.getElementById('createModal');if(document.getElementById('newLogisticsCompany'))return;const title=[...modal.querySelectorAll('.section-head h3')].find(x=>x.textContent==='司机与车辆'),body=title.closest('.section').querySelector('.section-body'),grids=body.querySelectorAll('.grid2'),typeSelect=grids[1].querySelector('select');const companyField=document.createElement('div');companyField.className='field';companyField.innerHTML='<label>物流公司 *</label><select id="newLogisticsCompany" onchange="refreshShipmentDrivers()"></select>';body.prepend(companyField);document.getElementById('newDriver').outerHTML='<select id="newDriver" onchange="applySelectedDriver()"><option value="">请选择司机</option></select>';document.getElementById('newDriverPhone').readOnly=true;document.getElementById('newDriverPhone').placeholder='选择司机后自动带入';document.getElementById('newCar').outerHTML='<select id="newCar" onchange="applySelectedVehicle()"><option value="">请选择车辆</option></select>';typeSelect.id='newVehicleType';typeSelect.disabled=true;const hint=document.createElement('div');hint.className='readonly-hint';hint.textContent='按物流公司筛选可用司机，选择司机后自动带入手机号及其关联车辆。';body.append(hint);const carrier=document.getElementById('newCarrier');carrier.closest('.field').querySelector('label').textContent='运输单号';carrier.placeholder='选填';const from=document.getElementById('newFrom');from.innerHTML='<option>卓希一号仓</option><option>卓希二号仓</option>';refreshShipmentCompanyOptions()}
function refreshShipmentCompanyOptions(){const select=document.getElementById('newLogisticsCompany');if(!select)return;const old=select.value,enabled=logisticsCompanies.filter(c=>c.status==='启用');select.innerHTML=enabled.map(c=>`<option value="${c.id}">${adminEscape(c.name)}</option>`).join('');select.value=enabled.some(c=>c.id===old)?old:(enabled[0]?.id||'');refreshShipmentDrivers()}
function refreshShipmentDrivers(){const companyId=document.getElementById('newLogisticsCompany')?.value,select=document.getElementById('newDriver');if(!select)return;const old=select.value,list=managedDrivers.filter(d=>d.companyId===companyId&&adminDriverQualified(d));select.innerHTML='<option value="">请选择资质有效司机</option>'+list.map(d=>`<option value="${d.id}">${adminEscape(d.name)} · ${adminEscape(d.phone)} · 资质有效</option>`).join('');select.value=list.some(d=>d.id===old)?old:'';applySelectedDriver()}
function applySelectedDriver(){const driver=managedDrivers.find(d=>d.id===document.getElementById('newDriver')?.value),phone=document.getElementById('newDriverPhone'),car=document.getElementById('newCar');if(!phone||!car)return;phone.value=driver?.phone||'';const vehicles=(driver?.vehicles||[]).map((v,i)=>({...v,index:i})).filter(adminVehicleQualified);car.innerHTML='<option value="">请选择资质有效车辆</option>'+vehicles.map(v=>`<option value="${v.index}">${adminEscape(v.plate)} · ${adminEscape(v.type)} · 资质有效</option>`).join('');if(vehicles.length)car.value=String(vehicles[0].index);applySelectedVehicle()}
function applySelectedVehicle(){const driver=managedDrivers.find(d=>d.id===document.getElementById('newDriver')?.value),vehicle=driver?.vehicles?.[Number(document.getElementById('newCar')?.value)];if(document.getElementById('newVehicleType'))document.getElementById('newVehicleType').value=vehicle?.type||'9.6米冷藏厢式货车'}
function prepareCreateFlow(){const modal=document.getElementById('createModal');modal.querySelector('h2').textContent='从订单创建发货单';modal.querySelector('.desc').textContent='选择已接单订单，商品和甲方信息自动带入；填写司机车辆后生成二维码';if(document.getElementById('sourceOrderField'))return;const field=document.createElement('div');field.id='sourceOrderField';field.className='field';field.innerHTML='<label>来源平台订单 *</label><select id="newSourceOrder" onchange="fillSourceOrder(this.value)"></select>';modal.querySelector('.desc').after(field);const buyer=document.createElement('div');buyer.className='field';buyer.innerHTML='<label>甲方预留手机号 *</label><input id="newBuyerPhone" type="tel" readonly>';modal.querySelector('.grid2').after(buyer);document.getElementById('newCustomer').readOnly=true;document.getElementById('newContact').readOnly=true;document.getElementById('newTo').readOnly=true;document.getElementById('newGoods').readOnly=true;document.getElementById('newQty').readOnly=true}
function fillSourceOrder(id){const o=orders.find(x=>x.id===id);if(!o)return;document.getElementById('newCustomer').value=o.customer;document.getElementById('newContact').value=`${o.receiver} ${o.buyerPhone}`;document.getElementById('newBuyerPhone').value=o.buyerPhone;const from=document.getElementById('newFrom');if(![...from.options].some(x=>x.value===o.from))from.add(new Option(o.from,o.from));from.value=o.from;document.getElementById('newTo').value=`${o.to}｜${o.address}`;document.getElementById('newGoods').value=(o.products||[]).map(p=>`${p.name}｜69码 ${p.barcode||'待补充'}｜${p.packsPerCase||'-'}包/箱｜${p.qty}${p.unit||'箱'}`).join('；');document.getElementById('newQty').value=o.qty;document.getElementById('newBatch').value=''}
function openCreate(id){prepareCreateFlow();prepareFleetSelectors();const pending=orders.filter(o=>o.status==='待创建发货单'),select=document.getElementById('newSourceOrder');select.innerHTML=pending.map(o=>`<option value="${o.id}" ${o.id===id?'selected':''}>${o.id} · ${o.customer} · ${o.qty}${o.unit||'箱'}</option>`).join('');if(!pending.length){toast('暂无待创建发货单的订单');return}const now=new Date(),eta=new Date(now.getTime()+48*3600000);document.getElementById('newShipTime').value=localInput(now);document.getElementById('newEta').value=localInput(eta);['newDriverPhone','newCarrier','newSeal','newRemark'].forEach(x=>document.getElementById(x).value='');refreshShipmentCompanyOptions();fillSourceOrder(select.value);showModal('createModal')}
function shipmentData(){const id=document.getElementById('newSourceOrder').value,o=orders.find(x=>x.id===id),driverRecord=managedDrivers.find(d=>d.id===document.getElementById('newDriver').value),company=companyById(document.getElementById('newLogisticsCompany').value),vehicle=driverRecord?.vehicles?.[Number(document.getElementById('newCar').value)],batch=document.getElementById('newBatch').value.trim();if(!o||!company||!driverRecord||!vehicle||!batch){toast('请完整填写商品批次，并选择物流公司、司机和车辆');return null}if(company.status!=='启用'||!adminDriverQualified(driverRecord)||!adminVehicleQualified(vehicle)){toast('物流公司、司机或车辆资质无效，不能创建发货单');return null}return{o,batch,driverId:driverRecord.id,driver:driverRecord.name,driverPhone:driverRecord.phone,car:vehicle.plate,vehicleType:vehicle.type,logisticsCompanyId:company.id,logisticsCompany:company.name}}
function createShipment(){const data=shipmentData();if(!data)return;if(!window.confirm(`请再次确认：创建发货单草稿，由“${data.logisticsCompany}”司机 ${data.driver}（${data.driverPhone}）驾驶 ${data.car} 承运？创建后仍需工厂确认发货。`))return;const {o,...fleet}=data,day=new Date().toISOString().slice(0,10).replaceAll('-','');Object.assign(o,{...fleet,ship:`FHD${day}${String(Date.now()).slice(-8)}`,status:'待发货',latest:'发货单已创建，等待工厂确认逐商品发货数量',time:'刚刚',temp:0,factoryQty:null,qrStatus:'有效',qrVersion:1,notifications:[{type:'发货单草稿已创建',target:'工厂物流',status:'已发送',time:new Date().toLocaleString('zh-CN',{hour12:false})}]});current=o;closeModal();render();toast('发货单已创建，状态为待发货');setTimeout(()=>openQR(o.id),650)}
function saveDraft(){const data=shipmentData();if(!data)return;const {o,...fleet}=data;Object.assign(o,fleet,{latest:'发货单草稿待提交'});closeModal();render();toast('发货单草稿已保存，平台订单仍待创建')}
const editSchemas={
'工厂发货':o=>[['提交人员','王志强'],['提交时间',o.factoryConfirmedAt||'2026-08-06 13:48'],['实际发货数量',`${o.factoryQty||o.qty}${o.unit||'箱'}`],['装车温度',`${o.temp||2.3}℃`],['发货仓库',o.from],['司机手机号',o.driverPhone||'138****0000'],['车辆信息',`${o.driver} · ${o.car}`],['封签号','']],
'司机揽收':o=>[['提交司机',o.driver],['揽收时间',o.pickupConfirmedAt||'2026-08-06 14:26'],['司机确认实际发货数量',`${o.pickupQty||o.factoryQty||o.qty}${o.unit||'箱'}`],['装车温度','2.4℃'],['现场位置',`${o.from}装货区`],['车辆信息',o.car],['异常情况','无异常'],['封签核验','无封签']],
'到货签收':o=>[['提交司机',o.driver],['到达时间',o.arrivalConfirmedAt||'2026-08-07 12:35'],['司机确认实际到货数量',`${o.arrivalQty||o.pickupQty||o.qty}${o.unit||'箱'}`],['开箱前温度','2.6℃'],['到货位置',o.to],['现场收货人',o.siteReceiver||o.receiver||'仓库收货人'],['现场收货人手机号',o.siteReceiverPhone||o.buyerPhone||'待补充'],['交付结果','正常签收'],['异常情况','无异常']],
'甲方确认':o=>[['签收人姓名',o.buyerSignerName||o.receiver||'甲方管理员'],['确认时间',o.buyerConfirmedAt||'2026-08-07 13:02'],['甲方实际签收数量',`${o.buyerSignedQty||o.arrivalQty||o.qty}${o.unit||'箱'}`],['签收人手机号',o.buyerSignerPhone||o.buyerPhone||'138****0000'],['签收照片',o.buyerSignPhotoName||'已上传1张'],['签收单（选填）',o.buyerReceiptDocumentName||'未上传'],['核验结果','商品、数量、温度、封签一致'],['确认结论','确认收货'],['确认备注','无']]
};
function prepareNodeEditor(){const modal=document.getElementById('editModal');if(document.getElementById('nodeEditor'))return;modal.querySelectorAll(':scope > .grid2').forEach(x=>x.hidden=true);document.getElementById('editStatus').closest('.field').hidden=true;const editor=document.createElement('div');editor.id='nodeEditor';editor.innerHTML='<div class="field"><label>更正节点</label><select id="editNodeSelect" onchange="renderNodeEditor(this.value)"><option>工厂发货</option><option>司机揽收</option><option>到货签收</option><option>甲方确认</option></select></div><div id="nodeEditFields" class="grid2"></div><div class="grid2"><div class="field"><label>节点状态</label><select id="nodeEditStatus"><option>已完成</option><option>异常</option><option>已作废</option></select></div><div class="field"><label>照片凭证处理</label><select id="nodePhotoAction"><option>保留原照片</option><option>补充上传照片</option><option>作废并重新上传</option></select></div></div>';document.getElementById('editReason').closest('.field').before(editor)}
function renderNodeEditor(stage){const original=editSchemas[stage](current),saved=current.nodeEdits?.[stage]?.fields,fields=saved||original;document.getElementById('nodeEditFields').innerHTML=fields.map(([label,value])=>`<div class="field"><label>${label}</label><input class="node-edit-input" data-label="${label}" value="${String(value).replaceAll('"','&quot;')}" placeholder="请输入${label}"></div>`).join('')}
function openEdit(id,stage){current=orders.find(o=>o.id===id);if(!current||current.status==='待创建发货单'){toast('请先创建发货单');return}prepareNodeEditor();const node=stage||'工厂发货';document.getElementById('editDesc').textContent=`${current.ship} · 当前版本 V${current.version||1}`;document.getElementById('editNodeSelect').value=node;document.getElementById('editReason').value='';renderNodeEditor(node);showModal('editModal')}
function saveEdit(){const stage=document.getElementById('editNodeSelect').value,reason=document.getElementById('editReason').value.trim();if(!reason){toast('请填写修改原因');return}const fields=[...document.querySelectorAll('.node-edit-input')].map(x=>[x.dataset.label,x.value.trim()]);const required=fields.filter(([label])=>!['封签号','确认备注','异常情况','签收单（选填）'].includes(label));if(required.some(x=>!x[1])){toast('请完整填写节点更正信息');return}if(!window.confirm(`请再次确认：提交“${stage}”节点更正申请？申请不会立即生效，需由另一管理员复核。`))return;correctionRequests.push({id:`CR${String(Date.now()).slice(-8)}`,orderId:current.id,ship:current.ship,stage,fields,reason,status:'待复核',requester:'周婷 · 物流管理员',requestedAt:new Date().toLocaleString('zh-CN',{hour12:false}),photoAction:document.getElementById('nodePhotoAction').value});closeModal();renderExceptionManagement();toast('更正申请已提交，等待复核管理员处理')}
function applyCorrectionRequest(r){const o=orders.find(x=>x.id===r.orderId);if(!o)return;const qty=r.fields.find(([label])=>label.includes('数量')),n=qty?parseFloat(qty[1]):NaN;if(!Number.isNaN(n)){if(r.stage==='工厂发货')o.factoryQty=n;if(r.stage==='司机揽收')o.pickupQty=n;if(r.stage==='到货签收')o.arrivalQty=n;if(r.stage==='甲方确认')o.buyerSignedQty=n}const temp=r.fields.find(([label])=>label.includes('温度')),t=temp?parseFloat(temp[1]):NaN;if(!Number.isNaN(t))o.temp=t;o.nodeEdits=o.nodeEdits||{};o.version=(o.version||1)+1;o.nodeEdits[r.stage]={fields:r.fields,reason:r.reason,status:'已复核生效',reviewer:'李娜 · 复核管理员',time:new Date().toLocaleString('zh-CN',{hour12:false})};o.latest=`${r.stage}更正已复核 · V${o.version}`;o.time='刚刚'}
function approveCorrection(id){const r=correctionRequests.find(x=>x.id===id);if(!r||r.status!=='待复核')return;if(!window.confirm(`请再次确认：以复核管理员“李娜”身份通过 ${r.id}？`))return;applyCorrectionRequest(r);r.status='已通过';r.reviewer='李娜 · 复核管理员';r.reviewedAt=new Date().toLocaleString('zh-CN',{hour12:false});render();renderExceptionManagement();toast('更正申请已复核通过并生成新数据版本')}
function rejectCorrection(id){const r=correctionRequests.find(x=>x.id===id);if(!r||r.status!=='待复核')return;if(!window.confirm(`确认驳回 ${r.id}？原始节点数据将保持不变。`))return;r.status='已驳回';r.reviewer='李娜 · 复核管理员';r.reviewedAt=new Date().toLocaleString('zh-CN',{hour12:false});renderExceptionManagement();toast('更正申请已驳回')}
function resolveException(id){const e=exceptionTickets.find(x=>x.id===id);if(!e||e.status!=='待处理')return;if(!window.confirm(`请再次确认：将异常工单 ${e.id} 标记为已闭环？`))return;e.status='已闭环';e.resolution='责任方已确认差异，补货/赔付结果已留档';e.resolvedAt=new Date().toLocaleString('zh-CN',{hour12:false});renderExceptionManagement();toast('异常工单已闭环')}
function renderExceptionManagement(){const er=document.getElementById('exceptionRows'),rr=document.getElementById('reviewRows');if(!er||!rr)return;document.getElementById('exceptionTotal').textContent=exceptionTickets.filter(x=>x.status==='待处理').length;document.getElementById('reviewTotal').textContent=correctionRequests.filter(x=>x.status==='待复核').length;document.getElementById('overdueTotal').textContent=orders.filter(x=>x.slaOverdue).length;er.innerHTML=exceptionTickets.length?exceptionTickets.map(e=>`<tr><td><div class="order">${e.id}</div><div class="sub">${e.ship}</div></td><td>${e.stage}<div class="sub">${e.type}</div></td><td>${e.reason}</td><td>${e.photoName}</td><td><span class="badge ${e.status==='待处理'?'red':'green'}">${e.status}</span></td><td>${e.status==='待处理'?`<button class="btn primary" onclick="resolveException('${e.id}')">处理并闭环</button>`:'已完成'}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">暂无异常工单</td></tr>';rr.innerHTML=correctionRequests.length?correctionRequests.slice().reverse().map(r=>`<tr><td><div class="order">${r.id}</div><div class="sub">${r.requestedAt}</div></td><td>${r.ship}<div class="sub">${r.stage}</div></td><td>${r.requester}</td><td>${r.reason}</td><td><span class="badge ${r.status==='待复核'?'amber':r.status==='已通过'?'green':'gray'}">${r.status}</span></td><td>${r.status==='待复核'?`<div class="actions"><button class="btn primary" onclick="approveCorrection('${r.id}')">通过</button><button class="btn danger" onclick="rejectCorrection('${r.id}')">驳回</button></div>`:r.reviewer||''}</td></tr>`).join(''):'<tr><td colspan="6" class="empty">暂无更正审核申请</td></tr>'}
function showModal(id){document.getElementById('overlay').classList.add('show');document.getElementById(id).classList.add('show')}function closeModal(){document.querySelectorAll('.modal').forEach(m=>m.classList.remove('show'));if(!document.getElementById('drawer').classList.contains('show'))document.getElementById('overlay').classList.remove('show')}function closeAll(){document.getElementById('overlay').classList.remove('show');document.getElementById('drawer').classList.remove('show');document.querySelectorAll('.modal').forEach(m=>m.classList.remove('show'))}function toast(msg){const t=document.getElementById('toast');t.textContent=msg;t.style.opacity=1;t.style.transform='translateX(-50%) translateY(0)';setTimeout(()=>{t.style.opacity=0;t.style.transform='translateX(-50%) translateY(20px)'},1800)}
