function installSignoffView(){const nav=document.querySelector('.nav'),anchor=document.getElementById('navCompanies'),link=document.createElement('a');link.id='navSignoffs';link.href='javascript:void(0)';link.onclick=()=>switchAdminView('signoffs');link.innerHTML='✓ <span>订单签收信息</span>';nav.insertBefore(link,anchor);const view=document.createElement('section');view.className='admin-view';view.id='signoffsView';view.hidden=true;view.innerHTML=`<div class="management-head"><div><h2>订单签收信息</h2><p>查看司机回传的签收时间、定位、卸货照片、签收单和备注</p></div><button class="btn" onclick="toast('签收信息已导出')">导出签收记录</button></div><div class="manager-summary"><div class="mini"><span>今日已签收</span><b>18</b></div><div class="mini"><span>待签收</span><b>26</b></div><div class="mini"><span>异常待复核</span><b>1</b></div></div><section class="toolbar"><div class="search"><input id="signoffSearch" placeholder="物流单号、订单号、客户、司机" oninput="renderSignoffs()"></div><select class="select" id="signoffStatus" onchange="renderSignoffs()"><option value="">全部状态</option><option>已签收</option><option>异常待复核</option></select><select class="select"><option>近30天</option><option>今日</option><option>近7天</option></select></section><section class="table-card"><table><thead><tr><th>物流单号 / 订单号</th><th>客户 / 司机</th><th>签收时间</th><th>定位信息</th><th>签收凭证</th><th>状态</th><th>操作</th></tr></thead><tbody id="signoffRows"></tbody></table></section>`;document.querySelector('.main').appendChild(view);renderSignoffs()}
function renderSignoffs(){const q=(document.getElementById('signoffSearch')?.value||'').toLowerCase(),s=document.getElementById('signoffStatus')?.value||'',list=signoffRecords.filter(x=>(!s||x.status===s)&&Object.values(x).join(' ').toLowerCase().includes(q));document.getElementById('signoffRows').innerHTML=list.length?list.map((x,i)=>`<tr><td><div class="order">${x.waybill}</div><div class="sub">${x.order}</div></td><td>${x.customer}<div class="sub">${x.driver} · ${x.phone}</div></td><td>${x.time}</td><td>${x.location}<div class="sub">GPS定位 · 精度18米</div></td><td>卸货照片 ${x.unload} 张<div class="sub">签收单 ${x.receipt} 张</div></td><td><span class="badge ${x.status==='已签收'?'green':'amber'}">${x.status}</span></td><td><button class="btn" onclick="openSignoff(${i})">查看详情</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">暂无符合条件的签收记录</td></tr>'}
function openSignoff(i){const x=signoffRecords[i];document.getElementById('detailTitle').textContent='签收信息详情';document.getElementById('detailSub').textContent=`${x.waybill} · ${x.customer}`;document.getElementById('detailBody').innerHTML=`<div class="summary"><div class="mini"><span>签收状态</span><b class="badge ${x.status==='已签收'?'green':'amber'}">${x.status}</b></div><div class="mini"><span>卸货照片</span><b>${x.unload} 张</b></div><div class="mini"><span>签收单</span><b>${x.receipt} 张</b></div><div class="mini"><span>数据来源</span><b>司机小程序</b></div></div><div class="section"><div class="section-head"><h3>签收基础信息</h3></div><div class="section-body"><div class="kv"><span>物流单号</span><b>${x.waybill}</b><span>关联订单</span><b>${x.order}</b><span>签收时间</span><b>${x.time}</b><span>提交司机</span><b>${x.driver} · ${x.phone}</b><span>定位信息</span><b style="grid-column:span 3">${x.location} · GPS精度18米</b><span>备注</span><b style="grid-column:span 3">${x.remark||'无'}</b></div></div></div><div class="section"><div class="section-head"><h3>现场签收凭证</h3><span class="badge green">共 ${x.unload+x.receipt} 张</span></div><div class="section-body"><div class="photos"><div class="photo">卸货照片 1<br>点击查看</div><div class="photo">卸货照片 2<br>点击查看</div><div class="photo">签字签收单<br>点击查看</div></div></div></div>`;document.getElementById('overlay').classList.add('show');document.getElementById('drawer').classList.add('show')}
const baseSwitchAdminView=switchAdminView;switchAdminView=function(view){const names=['orders','companies','drivers','exceptions','signoffs'];names.forEach(name=>{const panel=document.getElementById(`${name}View`),nav=document.getElementById(`nav${name[0].toUpperCase()+name.slice(1)}`);if(panel)panel.hidden=name!==view;if(nav)nav.classList.toggle('active',name===view)});document.getElementById('adminPageTitle').textContent={orders:'物流订单管理',companies:'物流公司管理',drivers:'司机与车辆管理',exceptions:'异常工单与更正审核',signoffs:'订单签收信息'}[view];if(view==='companies')renderCompanyManagement();if(view==='drivers')renderDriverManagement();if(view==='exceptions')renderExceptionManagement();if(view==='signoffs')renderSignoffs()}
function installOrderLinkedSignoffUpgrade(){
 const style=document.createElement('style');style.textContent=`.signoff-list{display:grid;gap:14px}.signoff-order{background:#fff;border:1px solid #e6e9ed;border-radius:10px;overflow:hidden;box-shadow:0 3px 12px rgba(21,35,50,.04)}.signoff-order-head{padding:11px 15px;background:#f7f9fb;border-bottom:1px solid #e6e9ed;display:flex;align-items:center;gap:20px;flex-wrap:wrap;font-size:12px}.signoff-order-head b{font-size:13px}.signoff-order-head .grow{flex:1}.signoff-order-body{display:grid;grid-template-columns:minmax(350px,2.1fr) minmax(150px,.7fr) minmax(190px,1fr) minmax(170px,.9fr) minmax(220px,1.1fr)}.signoff-cell{min-height:190px;padding:15px;border-right:1px solid #e6e9ed;display:flex;flex-direction:column;justify-content:center;font-size:13px;line-height:1.65}.signoff-cell:last-child{border-right:0}.signoff-products{justify-content:flex-start}.signoff-product{display:grid;grid-template-columns:52px 1fr auto;gap:11px;align-items:center;padding:8px 0;border-bottom:1px solid #f0f2f4}.signoff-product:last-child{border:0}.product-thumb{width:52px;height:52px;border-radius:8px;background:linear-gradient(145deg,#fff3dc,#ffd8ba);display:grid;place-items:center;color:#d65b25;font-size:22px}.product-name{font-weight:700;line-height:1.35}.product-meta{color:#8190a0;font-size:11px}.amount{font-size:17px;color:var(--red);font-weight:800;text-align:center}.signoff-status{display:flex;gap:7px;align-items:center;margin:3px 0}.signoff-status span:first-child{color:#84909c;width:58px}.signoff-actions{gap:9px;align-items:stretch}.signoff-actions .btn{width:100%}.signoff-empty{color:#9aa4ae}.upload-preview{display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-top:8px}.upload-slot{height:82px;border:1px dashed #ccd3da;border-radius:8px;background:#f8fafb;display:grid;place-items:center;text-align:center;color:#84909c;font-size:11px;position:relative;overflow:hidden}.upload-slot input{position:absolute;inset:0;opacity:0}.upload-slot img{width:100%;height:100%;object-fit:cover}@media(max-width:1200px){.signoff-order-body{grid-template-columns:1.7fr .7fr 1fr}.signoff-cell:nth-child(4),.signoff-cell:nth-child(5){border-top:1px solid #e6e9ed}.signoff-cell:nth-child(4){grid-column:1/3}}`;document.head.appendChild(style);
 const view=document.getElementById('signoffsView');view.innerHTML=`<div class="management-head"><div><h2>订单签收信息</h2><p>签收记录与原订单关联展示，可查看详情或由后台手动补录、编辑签收凭证</p></div><button class="btn primary" onclick="openSignoffEditor()">＋ 手动录入签收信息</button></div><div class="manager-summary"><div class="mini"><span>关联订单</span><b>${signoffRecords.length}</b></div><div class="mini"><span>已回传签收</span><b>${signoffRecords.filter(x=>x.status==='已签收').length}</b></div><div class="mini"><span>待补充/异常</span><b>${signoffRecords.filter(x=>x.status!=='已签收').length}</b></div></div><section class="toolbar"><div class="search"><input id="signoffSearch" placeholder="订单号、物流单号、客户、司机" oninput="renderSignoffs()"></div><select class="select" id="signoffStatus" onchange="renderSignoffs()"><option value="">全部签收状态</option><option>已签收</option><option>异常待复核</option><option>待上传</option></select><select class="select"><option>近30天订单</option><option>今日订单</option><option>近7天订单</option></select><button class="btn" onclick="toast('签收信息已导出')">导出</button></section><div class="signoff-list" id="signoffRows"></div>`;
 const modal=document.createElement('section');modal.className='modal';modal.id='signoffEditModal';modal.style.width='min(720px,94vw)';modal.innerHTML=`<h2 id="signoffEditTitle">手动录入签收信息</h2><div class="desc" id="signoffEditDesc">选择订单并补充签收时间、定位和现场凭证</div><div class="grid2"><div class="field"><label>关联订单 *</label><select id="signoffEditOrder"></select></div><div class="field"><label>物流单号 *</label><input id="signoffEditWaybill"></div></div><div class="grid2"><div class="field"><label>签收时间 *</label><input id="signoffEditTime" type="datetime-local"></div><div class="field"><label>定位信息 *</label><input id="signoffEditLocation" placeholder="请输入签收地址"></div></div><div class="grid2"><div class="field"><label>卸货照片 *</label><div class="upload-preview"><label class="upload-slot">＋ 上传照片<input id="signoffEditUnload" type="file" accept="image/*" multiple onchange="adminSignoffPreview(this)"></label><div class="upload-slot">支持多张<br>JPG/PNG</div></div></div><div class="field"><label>签字签收单 *</label><div class="upload-preview"><label class="upload-slot">＋ 上传签收单<input id="signoffEditReceipt" type="file" accept="image/*" multiple onchange="adminSignoffPreview(this)"></label><div class="upload-slot">需包含签字<br>及签收日期</div></div></div></div><div class="field"><label>备注</label><textarea id="signoffEditRemark" placeholder="填写数量差异、货损或其他说明"></textarea></div><div class="modal-foot"><button class="btn" onclick="closeModal()">取消</button><button class="btn primary" onclick="saveSignoffEdit()">保存签收信息</button></div>`;document.body.appendChild(modal);
 renderSignoffs();
}
function signoffOrderData(x,i){const linked=orders.find(o=>o.id===x.order)||{},samples=[[['椒麻大杂烩 · 脱骨侠','500g · 20包/箱',5],['无骨鸡爪 · 脱骨侠','500g · 20包/箱',5]],[['无骨鸡爪 · 酸辣柠檬味','508g · 20包/箱',180],['虎皮凤爪 · 卤香味','208g · 24包/箱',100]],[['藤椒无骨鸡爪','298g · 30包/箱',120]]];return{...x,amount:linked.amount||[185,5630,2480][i]||185,receiver:linked.receiver||x.customer,receiverPhone:linked.buyerPhone||'138****4096',address:linked.address||x.location,orderStatus:linked.status||'已发货',products:linked.products?.length?linked.products.map(p=>[p.name,p.spec,p.qty]):samples[i%samples.length]}}
renderSignoffs=function(){const q=(document.getElementById('signoffSearch')?.value||'').toLowerCase(),s=document.getElementById('signoffStatus')?.value||'',list=signoffRecords.map(signoffOrderData).filter(x=>(!s||x.status===s)&&Object.values(x).join(' ').toLowerCase().includes(q));document.getElementById('signoffRows').innerHTML=list.length?list.map(x=>{const idx=signoffRecords.findIndex(r=>r.waybill===x.waybill),products=x.products.map(p=>`<div class="signoff-product"><div class="product-thumb">鲜</div><div><div class="product-name">${adminEscape(p[0])}</div><div class="product-meta">${adminEscape(p[1]||'商品规格以订单为准')}</div></div><b>× ${p[2]}</b></div>`).join('');return `<article class="signoff-order"><div class="signoff-order-head"><span>订单编号：<b>${x.order}</b></span><span>下单时间：2026-08-${String(10-idx).padStart(2,'0')} 16:08:16</span><span>物流单号：<b>${x.waybill}</b></span><span>订单来源：<span class="badge gray">CRM</span></span><span class="grow"></span><span>创建人：<span class="badge amber">栗顾</span></span></div><div class="signoff-order-body"><div class="signoff-cell signoff-products">${products}</div><div class="signoff-cell"><div class="amount">¥${Number(x.amount).toFixed(2)}</div></div><div class="signoff-cell"><b>收货人：${adminEscape(x.receiver)}</b><span>手机：${adminEscape(x.receiverPhone)}</span><span>地址：${adminEscape(x.address)}</span></div><div class="signoff-cell"><div class="signoff-status"><span>订单状态</span><b class="badge blue">${adminEscape(x.orderStatus)}</b></div><div class="signoff-status"><span>签收状态</span><b class="badge ${x.status==='已签收'?'green':'amber'}">${x.status}</b></div><div class="signoff-status"><span>签收时间</span><b>${x.time||'待上传'}</b></div><div class="signoff-status"><span>签收凭证</span><b>${x.unload+x.receipt} 张</b></div></div><div class="signoff-cell signoff-actions"><button class="btn" onclick="openSignoff(${idx})">查看订单及签收详情</button><button class="btn primary" onclick="openSignoffEditor(${idx})">${x.status==='待上传'?'上传签收信息':'编辑签收信息'}</button><span class="sub">提交司机：${x.driver} · ${x.phone}</span></div></div></article>`}).join(''):'<div class="card empty">暂无符合条件的订单签收信息</div>'}
openSignoff=function(i){const x=signoffOrderData(signoffRecords[i],i),products=x.products.map(p=>`<div class="goods" style="margin-bottom:8px"><div class="goods-head"><span>${adminEscape(p[0])}</span><span class="qty">× ${p[2]}</span></div><div class="goods-meta">${adminEscape(p[1]||'商品规格以订单为准')}</div></div>`).join('');document.getElementById('detailTitle').textContent='订单及签收详情';document.getElementById('detailSub').textContent=`${x.order} · ${x.waybill}`;document.getElementById('detailBody').innerHTML=`<div class="summary"><div class="mini"><span>订单状态</span><b class="badge blue">${x.orderStatus}</b></div><div class="mini"><span>签收状态</span><b class="badge ${x.status==='已签收'?'green':'amber'}">${x.status}</b></div><div class="mini"><span>订单金额</span><b style="color:var(--red)">¥${Number(x.amount).toFixed(2)}</b></div><div class="mini"><span>签收凭证</span><b>${x.unload+x.receipt} 张</b></div></div><div class="section"><div class="section-head"><h3>关联订单信息</h3><button class="btn" onclick="openDetail('${x.order}')">查看原订单详情</button></div><div class="section-body"><div class="kv"><span>订单编号</span><b>${x.order}</b><span>物流单号</span><b>${x.waybill}</b><span>客户</span><b>${adminEscape(x.customer)}</b><span>收货人</span><b>${adminEscape(x.receiver)}</b><span>联系电话</span><b>${adminEscape(x.receiverPhone)}</b><span>收货地址</span><b style="grid-column:span 3">${adminEscape(x.address)}</b></div><div style="margin-top:14px">${products}</div></div></div><div class="section"><div class="section-head"><h3>签收信息</h3><button class="btn primary" onclick="closeAll();openSignoffEditor(${i})">编辑签收信息</button></div><div class="section-body"><div class="kv"><span>签收时间</span><b>${x.time}</b><span>提交司机</span><b>${x.driver} · ${x.phone}</b><span>定位信息</span><b style="grid-column:span 3">${adminEscape(x.location)} · GPS精度18米</b><span>卸货照片</span><b>${x.unload} 张</b><span>签字签收单</span><b>${x.receipt} 张</b><span>备注</span><b style="grid-column:span 3">${adminEscape(x.remark||'无')}</b></div><div class="photos" style="margin-top:14px"><div class="photo">卸货照片 1<br>点击查看</div><div class="photo">卸货照片 2<br>点击查看</div><div class="photo">签字签收单<br>点击查看</div></div></div></div>`;document.getElementById('overlay').classList.add('show');document.getElementById('drawer').classList.add('show')}
openSignoffEditor=function(i){const editing=Number.isInteger(i),x=editing?signoffRecords[i]:null,select=document.getElementById('signoffEditOrder');select.innerHTML=orders.slice(0,8).map(o=>`<option value="${o.id}">${o.id} · ${o.customer}</option>`).join('');document.getElementById('signoffEditTitle').textContent=editing?'编辑签收信息':'手动录入签收信息';document.getElementById('signoffEditDesc').textContent=editing?`${x.order} · ${x.customer}`:'选择订单并补充签收时间、定位和现场凭证';select.value=x?.order||orders[0]?.id||'';select.disabled=editing;document.getElementById('signoffEditWaybill').value=x?.waybill||'';document.getElementById('signoffEditTime').value=x?.time?.replace(' ','T')||localInput(new Date());document.getElementById('signoffEditLocation').value=x?.location||'';document.getElementById('signoffEditRemark').value=x?.remark||'';document.getElementById('signoffEditModal').dataset.index=editing?i:'';showModal('signoffEditModal')}
function adminSignoffPreview(input){if(!input.files?.length)return;const slot=input.closest('.upload-slot'),r=new FileReader();r.onload=e=>slot.innerHTML=`<img src="${e.target.result}">`;r.readAsDataURL(input.files[0])}
function saveSignoffEdit(){const modal=document.getElementById('signoffEditModal'),idx=modal.dataset.index,orderId=document.getElementById('signoffEditOrder').value,linked=orders.find(o=>o.id===orderId),waybill=document.getElementById('signoffEditWaybill').value.trim(),time=document.getElementById('signoffEditTime').value,location=document.getElementById('signoffEditLocation').value.trim();if(!orderId||!waybill||!time||!location){toast('请完整填写关联订单、物流单号、签收时间和定位');return}const data={waybill,order:orderId,customer:linked?.customer||'关联客户',driver:linked?.driver||'后台补录',phone:linked?.driverPhone||'—',time:time.replace('T',' '),location,unload:document.getElementById('signoffEditUnload').files?.length||1,receipt:document.getElementById('signoffEditReceipt').files?.length||1,remark:document.getElementById('signoffEditRemark').value.trim(),status:'已签收'};if(idx==='')signoffRecords.unshift(data);else Object.assign(signoffRecords[Number(idx)],data);closeModal();renderSignoffs();toast(idx===''?'签收信息已手动录入':'签收信息已更新')}
function installSlaView(){
 const style=document.createElement('style');style.textContent=`.sla-shell{display:grid;grid-template-columns:240px minmax(0,1fr);gap:16px}.sla-aside,.sla-panel{background:#fff;border:1px solid #eeeae8;border-radius:14px}.sla-aside{padding:10px;height:max-content;position:sticky;top:84px}.sla-tab{width:100%;border:0;background:transparent;border-radius:9px;padding:12px;text-align:left;color:#6f6763;cursor:pointer;display:flex;justify-content:space-between;align-items:center}.sla-tab.active{background:#fff0ed;color:var(--red);font-weight:800}.sla-tab small{background:#f2efed;color:#8a817d;border-radius:99px;padding:2px 7px}.sla-tab.active small{background:#ffdcd6;color:var(--red)}.sla-panel{padding:18px}.sla-panel-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;padding-bottom:16px;border-bottom:1px solid var(--line)}.sla-panel-head h3{margin:0 0 5px;font-size:17px}.sla-panel-head p{margin:0;color:var(--muted);font-size:12px}.sla-card{border:1px solid #e9e4e1;border-radius:12px;margin-top:14px;overflow:hidden}.sla-card-head{padding:13px 15px;background:#fbfaf9;display:flex;justify-content:space-between;align-items:center}.sla-card-head b{font-size:14px}.sla-card-body{padding:15px;display:grid;grid-template-columns:1.5fr repeat(3,minmax(105px,.7fr));gap:14px;align-items:end}.sla-card-body.product{grid-template-columns:1fr 1fr}.sla-field label{display:block;font-size:11px;color:var(--muted);margin-bottom:6px}.sla-field input,.sla-field select{width:100%;height:38px;border:1px solid var(--line);border-radius:8px;padding:0 10px;background:#fff}.sla-input{display:flex;align-items:center;border:1px solid var(--line);border-radius:8px;overflow:hidden}.sla-input input{border:0;border-radius:0;min-width:0}.sla-input span{padding:0 10px;color:#8a817d;background:#faf8f7;height:36px;display:flex;align-items:center}.toggle{width:42px;height:24px;border:0;border-radius:99px;background:#c9c2be;padding:3px;cursor:pointer;transition:.2s}.toggle:after{content:'';display:block;width:18px;height:18px;background:#fff;border-radius:50%;transition:.2s;box-shadow:0 1px 3px #888}.toggle.on{background:var(--green)}.toggle.on:after{transform:translateX(18px)}.sla-rule-note{grid-column:1/-1;background:#f7f9fb;border-radius:8px;padding:10px 12px;font-size:12px;color:#5f6c78;display:flex;gap:8px}.sla-actions{position:sticky;bottom:0;margin:18px -18px -18px;padding:13px 18px;background:rgba(255,255,255,.96);border-top:1px solid var(--line);display:flex;justify-content:space-between;align-items:center}.sla-actions span{color:var(--muted);font-size:12px}.sla-legend{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.driver-rule{display:grid;grid-template-columns:1fr 1fr;gap:14px}.driver-option{border:1px solid var(--line);border-radius:10px;padding:14px}.driver-option label{font-weight:700}.driver-option p{font-size:12px;color:var(--muted);margin:6px 0 0}.driver-option input{margin-right:7px}.sla-dirty{color:var(--amber)!important;font-weight:700}@media(max-width:900px){.sla-shell{grid-template-columns:1fr}.sla-aside{position:static;display:flex;overflow:auto}.sla-tab{min-width:150px}.sla-card-body{grid-template-columns:1fr 1fr}.sla-card-body.product,.driver-rule{grid-template-columns:1fr}.sla-rule-note{grid-column:1/-1}}`;
 document.head.appendChild(style);
 const nav=document.querySelector('.nav'),link=document.createElement('a');link.id='navSla';link.href='javascript:void(0)';link.onclick=()=>switchAdminView('sla');link.innerHTML='◷ <span>时效预警策略</span>';nav.appendChild(link);
 const view=document.createElement('section');view.className='admin-view';view.id='slaView';view.hidden=true;view.innerHTML=`<div class="management-head"><div><h2>发货时效预警策略</h2><p>统一配置订单从商品备货到签收的时效口径，超时后自动进入异常预警</p></div><span class="badge green">策略已启用</span></div><div class="sla-legend"><span class="badge gray">提醒：临近时限</span><span class="badge amber">预警：达到时限</span><span class="badge red">严重：超过时限</span></div><div class="sla-shell"><aside class="sla-aside"><button class="sla-tab active" onclick="selectSlaGroup('product',this)">商品发货时效 <small>2</small></button><button class="sla-tab" onclick="selectSlaGroup('flow',this)">订单履约节点 <small>6</small></button><button class="sla-tab" onclick="selectSlaGroup('driver',this)">司机与车辆信息 <small>1</small></button></aside><div class="sla-panel"><div id="slaContent"></div><div class="sla-actions"><span id="slaSaveState">上次保存：今天 10:26</span><div><button class="btn" onclick="resetSla()">恢复默认</button> <button class="btn primary" onclick="saveSla()">保存并生效</button></div></div></div></div>`;document.querySelector('.main').appendChild(view);renderSla('product')
}
const slaDefaults={product:{stock:24,noStock:72},rules:[
 {id:'finance',name:'财务审核',from:'订单提交',to:'财务审核通过',value:2,unit:'小时',warn:80,on:true,note:'从订单提交开始计时，财务审核通过后停止。'},
 {id:'accept',name:'接单',from:'财务审核通过',to:'平台完成接单',value:1,unit:'小时',warn:80,on:true,note:'仅统计财务审核通过且未接单的订单。'},
 {id:'ship',name:'发货',from:'平台接单',to:'旺店通审核订单',value:24,unit:'小时',warn:75,on:true,note:'以旺店通“订单审核完成”时间作为发货节点完成时间。'},
 {id:'pickup',name:'揽收',from:'旺店通审核',to:'ERP同步WMS',value:4,unit:'小时',warn:75,on:true,note:'ERP成功同步 WMS 后停止计时，失败重试不重置起算时间。'},
 {id:'logistics',name:'物流信息获取',from:'ERP同步WMS',to:'获取首条物流轨迹',value:6,unit:'小时',warn:80,on:true,note:'按物流单号轮询；获取首条有效轨迹后视为完成。'},
 {id:'sign',name:'签收',from:'获取物流信息',to:'物流签收',value:72,unit:'小时',warn:80,on:true,note:'有物流信息按签收状态判断；无物流信息时按配置时效直接预警。'}],driver:{required:true,plate:true,source:'司机端上传',wdt:false}};
let slaConfig=(()=>{try{return JSON.parse(localStorage.getItem('tgx-sla-config'))||structuredClone(slaDefaults)}catch(e){return structuredClone(slaDefaults)}})(),slaGroup='product';
function selectSlaGroup(group,el){slaGroup=group;document.querySelectorAll('.sla-tab').forEach(x=>x.classList.remove('active'));el.classList.add('active');renderSla(group)}
function slaRuleCard(r){return `<article class="sla-card"><div class="sla-card-head"><b>${r.name}时效</b><button class="toggle ${r.on?'on':''}" aria-label="启用${r.name}时效" onclick="toggleSla('${r.id}',this)"></button></div><div class="sla-card-body"><div class="sla-field"><label>计时区间</label><select onchange="markSlaDirty()"><option>${r.from} → ${r.to}</option></select></div><div class="sla-field"><label>时效阈值</label><div class="sla-input"><input type="number" min="1" value="${r.value}" data-rule="${r.id}" data-key="value" oninput="updateSlaRule(this)"><span>${r.unit}</span></div></div><div class="sla-field"><label>提前提醒</label><div class="sla-input"><input type="number" min="1" max="99" value="${r.warn}" data-rule="${r.id}" data-key="warn" oninput="updateSlaRule(this)"><span>%</span></div></div><div class="sla-field"><label>超时动作</label><select onchange="markSlaDirty()"><option>创建异常工单</option><option>仅消息提醒</option><option>消息提醒并升级</option></select></div><div class="sla-rule-note">ⓘ ${r.note}</div></div></article>`}
function renderSla(group){const c=document.getElementById('slaContent');if(!c)return;if(group==='product')c.innerHTML=`<div class="sla-panel-head"><div><h3>商品发货时效</h3><p>按商品库存状态维护承诺发货时间，作为订单发货预警的基础。</p></div></div><article class="sla-card"><div class="sla-card-head"><b>库存状态对应时效</b><span class="badge blue">商品级配置</span></div><div class="sla-card-body product"><div class="sla-field"><label>有货商品发货时效</label><div class="sla-input"><input type="number" min="1" value="${slaConfig.product.stock}" oninput="slaConfig.product.stock=+this.value;markSlaDirty()"><span>小时</span></div></div><div class="sla-field"><label>无货商品发货时效</label><div class="sla-input"><input type="number" min="1" value="${slaConfig.product.noStock}" oninput="slaConfig.product.noStock=+this.value;markSlaDirty()"><span>小时</span></div></div><div class="sla-rule-note">ⓘ 同一订单包含多个商品时，以最晚承诺发货时间作为订单时效；商品单独配置时优先使用商品值。</div></div></article>`;else if(group==='flow')c.innerHTML=`<div class="sla-panel-head"><div><h3>订单履约节点</h3><p>每个节点均可独立启停并设置阈值，修改后仅影响新进入该节点的订单。</p></div></div>${slaConfig.rules.map(slaRuleCard).join('')}`;else c.innerHTML=`<div class="sla-panel-head"><div><h3>司机与车辆信息</h3><p>配置揽收前的信息完整性要求，并预留旺店通自动采集能力。</p></div></div><article class="sla-card"><div class="sla-card-head"><b>司机信息采集规则</b><button class="toggle ${slaConfig.driver.required?'on':''}" onclick="slaConfig.driver.required=!slaConfig.driver.required;this.classList.toggle('on');markSlaDirty()"></button></div><div class="sla-card-body product"><div class="sla-field"><label>信息采集节点</label><select onchange="markSlaDirty()"><option>司机揽收前</option><option>创建发货单时</option></select></div><div class="sla-field"><label>当前采集方式</label><select onchange="slaConfig.driver.source=this.value;markSlaDirty()"><option ${slaConfig.driver.source==='司机端上传'?'selected':''}>司机端上传</option><option>后台管理员录入</option></select></div><div class="sla-rule-note">ⓘ 司机姓名、手机号和车牌号为必填项；缺失时禁止完成揽收，并生成信息缺失提醒。</div><div class="driver-rule"><div class="driver-option"><label><input type="checkbox" ${slaConfig.driver.plate?'checked':''} onchange="slaConfig.driver.plate=this.checked;markSlaDirty()">车牌号必填</label><p>支持司机端拍照上传或手动输入，后台可复核。</p></div><div class="driver-option"><label><input type="checkbox" ${slaConfig.driver.wdt?'checked':''} disabled>旺店通自动采集</label><p>待确认旺店通接口能力后开放，当前由司机端上传。</p></div></div></div></article>`}
function updateSlaRule(input){const r=slaConfig.rules.find(x=>x.id===input.dataset.rule);r[input.dataset.key]=+input.value;markSlaDirty()}
function toggleSla(id,btn){const r=slaConfig.rules.find(x=>x.id===id);r.on=!r.on;btn.classList.toggle('on',r.on);markSlaDirty()}
function markSlaDirty(){const s=document.getElementById('slaSaveState');s.textContent='有未保存的修改';s.classList.add('sla-dirty')}
function saveSla(){localStorage.setItem('tgx-sla-config',JSON.stringify(slaConfig));const s=document.getElementById('slaSaveState');s.textContent='已保存并生效 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});s.classList.remove('sla-dirty');toast('时效预警策略已保存并生效')}
function resetSla(){slaConfig=structuredClone(slaDefaults);renderSla(slaGroup);markSlaDirty();toast('已恢复默认配置，请保存后生效')}
installSignoffView();installOrderLinkedSignoffUpgrade();installSlaView();
const switchWithSla=switchAdminView;switchAdminView=function(view){if(view==='sla'){['orders','companies','drivers','exceptions','signoffs','sla'].forEach(name=>{const panel=document.getElementById(`${name}View`),nav=document.getElementById(`nav${name[0].toUpperCase()+name.slice(1)}`);if(panel)panel.hidden=name!==view;if(nav)nav.classList.toggle('active',name===view)});document.getElementById('adminPageTitle').textContent='时效预警策略';renderSla(slaGroup)}else switchWithSla(view)};
prepareCreateFlow();prepareFleetSelectors();refreshCompanySelectors();renderCompanyManagement();renderDriverManagement();renderExceptionManagement();render();

